<?php use ImWiki\Security\Csrf;use ImWiki\Security\Html;use ImWiki\Support\Url;$title='Ustaw nowe hasło'; ?>
<div class="auth-card"><h1>Ustaw nowe hasło</h1><?php if($done):?><div class="alert success">Hasło zostało zmienione. Pozostałe sesje i aktywne API tokeny zostały unieważnione.</div><a class="button" href="<?=Html::e(Url::to('/login'))?>">Przejdź do logowania</a><?php elseif(!$valid):?><div class="alert danger"><?=Html::e($error?:'Link resetu jest nieważny lub wygasł.')?></div><a href="<?=Html::e(Url::to('/forgot-password'))?>">Wygeneruj nowy link</a><?php else:?><?php if($error):?><div class="alert danger"><?=Html::e($error)?></div><?php endif;?><form method="post" action="<?=Html::e(Url::to('/password-reset'))?>" class="stack-form"><?=Csrf::field()?><input type="hidden" name="token" value="<?=Html::e($token)?>"><label>Nowe hasło<input type="password" name="password" minlength="10" autocomplete="new-password" required></label><label>Powtórz hasło<input type="password" name="password_repeat" minlength="10" autocomplete="new-password" required></label><button class="button">Zmień hasło</button></form><?php endif;?></div>
